import pyomo.environ as pyo

DATA = {
    "departments": ["X", "Y", "Z"],
    "cost": {"X": 5000, "Y": 4000, "Z": 6000},
    "experience_weight": {"X": 5, "Y": 3, "Z": 7},
    "total_hires": 50,
    "experience_min": 200,
    "min_X": 10,
    "max_Y": 20,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.D = pyo.Set(initialize=d["departments"])

    # Bounds per department: X >= 10, Y <= 20, Z >= 0
    def hire_bounds(m, dept):
        lb = 0
        ub = None
        if dept == "X":
            lb = d["min_X"]
        if dept == "Y":
            ub = d["max_Y"]
        return (lb, ub)

    model.hires = pyo.Var(
        model.D,
        domain=pyo.NonNegativeIntegers,
        bounds=hire_bounds,
    )

    # Objective: minimise total hiring cost
    def obj_rule(m):
        return sum(d["cost"][dept] * m.hires[dept] for dept in m.D)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Exactly 50 new employees total
    def total_hires_rule(m):
        return sum(m.hires[dept] for dept in m.D) == d["total_hires"]

    model.total_hires = pyo.Constraint(rule=total_hires_rule)

    # Experience score at least 200
    def experience_rule(m):
        return sum(
            d["experience_weight"][dept] * m.hires[dept] for dept in m.D
        ) >= d["experience_min"]

    model.experience = pyo.Constraint(rule=experience_rule)

    # At least 10 hires in department X
    def min_x_rule(m):
        return m.hires["X"] >= d["min_X"]

    model.min_X = pyo.Constraint(rule=min_x_rule)

    # No more than 20 hires in department Y
    def max_y_rule(m):
        return m.hires["Y"] <= d["max_Y"]

    model.max_Y = pyo.Constraint(rule=max_y_rule)

    return model


